function validate([messages, senders]) {
  if (!Array.isArray(messages) || !Array.isArray(senders) || messages.length !== senders.length) return 'messages and senders need the same length.';
  if (messages.length < 1 || messages.length > 10000) return 'There are 1 to 10^4 messages.';
  for (const m of messages) {
    if (typeof m !== 'string' || m.length < 1 || m.length > 100) return 'Each message has 1 to 100 characters.';
    if (!/^[A-Za-z]+( [A-Za-z]+)*$/.test(m)) return 'A message is letters-only words joined by single spaces, with no space at either end.';
  }
  for (const s of senders) {
    if (typeof s !== 'string' || !/^[A-Za-z]{1,10}$/.test(s)) return 'Each sender name is 1 to 10 English letters.';
  }
  return null;
}

