function largestWordCount(messages, senders) {
  const wordCount = new Map();
  for (let i = 0; i < messages.length; i++) {
    let words = 1;
    for (const ch of messages[i]) {
      if (ch === ' ') {
        words++;
      }
    }
    const total = (wordCount.get(senders[i]) ?? 0) + words;
    wordCount.set(senders[i], total);
  }
  let best = '';
  let bestCount = 0;
  for (const [sender, count] of wordCount) {
    if (count > bestCount || (count === bestCount && sender > best)) {
      best = sender;
      bestCount = count;
    }
  }
  return best;
}

