function largestWordCount(messages, senders) {
  const names = [...new Set(senders)];
  const totals = names.map(name => {
    let sum = 0;
    for (let i = 0; i < messages.length; i++) if (senders[i] === name) sum += messages[i].split(' ').length;
    return sum;
  });
  const order = names.map((_, i) => i);
  // Highest total first; among equal totals, the greater name (by character codes) first.
  order.sort((a, b) => totals[b] - totals[a] || (names[a] < names[b] ? 1 : names[a] > names[b] ? -1 : 0));
  return names[order[0]];
}

