function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const letters = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const word = (maxLen, pool) => Array.from({ length: int(1, maxLen) }, () => pool[Math.floor(rand() * pool.length)]).join('');
  let pool;
  if (size === 'large') {
    pool = Array.from({ length: 25 }, () => word(10, letters));
  } else {
    // Tiny names that differ by case or by a prefix make ties and ordering mistakes likely.
    const names = ['a', 'A', 'b', 'B', 'ab', 'aB', 'Ab', 'ba', 'Z', 'z'];
    pool = Array.from({ length: int(1, 4) }, () => names[Math.floor(rand() * names.length)]);
  }
  const n = size === 'large' ? 2000 : int(1, 6);
  const maxWords = size === 'large' ? 15 : 4;
  const messages = [];
  const senders = [];
  for (let i = 0; i < n; i++) {
    const parts = [];
    const count = int(1, maxWords);
    for (let w = 0; w < count; w++) {
      const next = word(size === 'large' ? 6 : 3, letters);
      if (parts.join(' ').length + (parts.length ? 1 : 0) + next.length > 100) break;
      parts.push(next);
    }
    messages.push(parts.join(' '));
    senders.push(pool[Math.floor(rand() * pool.length)]);
  }
  return [messages, senders];
}
